-- ScholarBridgeAi — Scholarship rewrite pass 33 (Canada)
-- Verified 2026-10-25 against the providers' own pages (cited in source_url).
-- Canadian universities publish their awards in CAD, so award_amount carries the published CAD figure
-- and amount_usd_value stays 0 (the app converts only when the currency is USD).

-- 562 Dalhousie — a portfolio of 2,000+ entrance awards, not one scholarship
UPDATE scholarships SET
  title = 'Dalhousie General Entrance Awards (International Applicants)',
  description = 'Dalhousie does not run a single international scholarship; it runs a portfolio of more than 2,000 entrance awards, with values running from about CAD 1,000 to CAD 80,000 depending on the award and whether it is paid once or over four years. International students are eligible for the general pool and enter it by submitting the General Entrance Award application after the admission application. The academic threshold is typically an 80% admission average or 26 predicted or anticipated IB points, calculated from the five courses required for the chosen program rather than from every subject taken, and award decisions use Grade 12 first-semester final grades, so marks that arrive later do not reassess the award. Awards may be one-time or renewable for up to four years. Several named awards sit inside the pool and are worth knowing because they are aimed at specific groups: the CorpFinance International Limited (Kevin Andrews) Indian Scholarship at CAD 15,000 for Indian students entering the Bachelor of Commerce, the Sankofa Scholarship at CAD 48,000 as CAD 12,000 a year for four years for one international student of Black or African descent from the Caribbean, the Murray Family Jamaican Engineering Scholarship at CAD 88,000 for students from Jamaica, and the Leacross Women in Technology Entrance Scholarship at CAD 10,000 over two years, which needs a separate application by 1 March. Transfer students are generally not eligible.',
  requirements = 'Be applying to Dalhousie directly from high school, or be a mature student with no transferable post-secondary study, and be starting in the fall term. Meet the academic requirement, typically an 80% average or 26 predicted or anticipated IB points, using the five courses required for the chosen program. Submit the admission application through the Dalhousie application portal and then complete the General Entrance Award application, which covers scholarships based on academic achievement, bursaries based on financial need and hybrid awards based on merit, leadership and need. Submit all required documents before the deadline, because award decisions are based on Grade 12 first-semester final grades. Note that transfer students are generally not eligible. Awards tied to a country or heritage, such as the Indian, Jamaican and Sankofa scholarships, require that specific background.',
  coverage_type = 'Partial Funding', award_basis = 'range', award_amount = 80000, award_currency = 'CAD', award_period = 'total',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based and need-based entrance awards',
  tuition_coverage = 'A portfolio rather than a single value: roughly CAD 1,000 to CAD 80,000 per award, paid once or renewable for up to four years. Most awards are partial and Dalhousie does not offer a full ride through the entrance pool.',
  english_requirements = 'The awards set no separate English score; the Dalhousie admission English requirement for the chosen program applies.',
  required_documents = '["Dalhousie admission application through the application portal","General Entrance Award application","Transcript with Grade 12 first-semester final grades","Evidence of leadership, extracurricular involvement and community service","Financial need information where a bursary or hybrid award is claimed","Separate application for the Leacross Women in Technology award by 1 March"]',
  deadline = '15 February 2027 for the 2027-28 General Entrance Award program, which opens on 1 October 2026',
  deadline_date = '2027-02-15', deadline_type = 'fixed', application_status = 'upcoming',
  website_url = 'https://www.dal.ca/admissions/scholarships-financial-aid/scholarships/future-undergraduate-student-awards.html',
  source_url = 'https://www.dal.ca/admissions/scholarships-financial-aid/scholarships/future-undergraduate-student-awards.html',
  application_url = 'https://apply.dal.ca/apply/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the Dalhousie University future undergraduate student awards page fetched 2026-10-25, which states that Dalhousie offers 2,000+ entrance awards each year with an approximate value range of CAD 1,000 to CAD 80,000 yearly and over four years, that entrance awards are applied for through the General Entrance Award application after the admission application, that eligibility typically requires an 80% average or 26 predicted or anticipated IB points calculated from the five required courses, that all students domestic and international are eligible, that gap-year students may still apply and transfer students are generally not eligible, that award decisions use Grade 12 first-semester final grades, and that the 2027-28 General Entrance Award program opens on 1 October 2026 with a deadline of 15 February 2027; the same page lists the CorpFinance Indian Scholarship at CAD 15,000, the Sankofa Scholarship at CAD 48,000 for an international student of Black or African descent from the Caribbean, the Murray Family Jamaican Engineering Scholarship at CAD 88,000, and the Leacross Women in Technology Entrance Scholarship at CAD 10,000 over two years with a separate application and a 1 March deadline. CORRECTIONS: the row was titled Dalhousie University Scholarships for International Students, carried an invented USD 21,000, listed all three degree levels and gave an April 1 deadline. There is no single Dalhousie international scholarship of that size; the real instrument is a portfolio entered through one general application with a 15 February 2027 deadline. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the published ceiling of CAD 80,000.'
WHERE id = 562;

-- 622 McMaster — the Award of Excellence is the flagship and it is genuinely large
UPDATE scholarships SET
  title = 'McMaster University Award of Excellence',
  description = 'McMaster is one of the few Canadian universities that publishes a six-figure entrance award for international students, and this is it: the McMaster University Award of Excellence is valued at up to CAD 200,000 over four years for international fee-paying students who have excelled in the classroom and contributed to their communities. It is open to students entering Level 1 in Business, Engineering, Humanities, Science or Social Sciences, and the application opens on 1 November 2026 with a deadline of 19 February 2027 at 11:59 p.m. Eastern through the AwardSpring platform. It is renewable in Levels 2, 3 and 4 for a total of four years provided the student stays in the faculty to which they were originally admitted, remains full-time and continues to pay international tuition - if tuition changes to domestic status the award stops. Payment is split in two: 50% after the fall drop-and-add period and 50% after the winter one. McMaster also says it holds over CAD 20 million in awards for international fee-paying undergraduates, ranging from CAD 7,500 to 200,000, and a student may hold one application-based award and one automatic award at the same time. The automatic ones are worth knowing too: the Engineering International Entrance Award at CAD 10,000 and the Computer Science International Scholars Award at CAD 10,000 are one-time and need no application, and Science runs a Global Scholars Award at CAD 10,000 on entry plus CAD 7,500 a year thereafter.',
  requirements = 'Be an international fee-paying student entering Level 1 of a first baccalaureate degree at McMaster in Business, Engineering, Humanities, Science or Social Sciences for the Award of Excellence. Submit the AwardSpring application between 1 November 2026 and 19 February 2027 at 11:59 p.m. Eastern. Finalise the offer of admission and clear any conditions. Enrol full time in the fall and winter terms and remain in the faculty to which you were admitted for Levels 2 to 4 to keep the award renewable. Continue paying international tuition fees, because a change to domestic fee status ends eligibility. Automatic faculty awards, such as the Engineering International Entrance Award and the Computer Science International Scholars Award at CAD 10,000 each, require no application. A student may receive one entrance award based on academic standing and one based on an application or other earned merit.',
  coverage_type = 'Partial Funding', award_basis = 'range', award_amount = 200000, award_currency = 'CAD', award_period = 'total',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based and earned-merit entrance awards',
  tuition_coverage = 'Up to CAD 200,000 over four years for the Award of Excellence, plus separate faculty awards including one-time CAD 10,000 entrance awards and renewable CAD 7,500 to 35,000 faculty awards. McMaster does not describe any of these as covering the full cost of attendance.',
  english_requirements = 'The awards set no separate English score; the McMaster admission English requirement for the chosen program applies.',
  required_documents = '["McMaster admission application through OUAC","AwardSpring application for the Award of Excellence","Academic transcripts and final admission average as calculated by the faculty","Evidence of community contribution and leadership","Clearance of admission conditions and acceptance of the offer"]',
  deadline = '19 February 2027 at 11:59 p.m. Eastern for the Award of Excellence, with the application opening on 1 November 2026',
  deadline_date = '2027-02-19', deadline_type = 'fixed', application_status = 'upcoming',
  website_url = 'https://future.mcmaster.ca/internationalawards/',
  source_url = 'https://future.mcmaster.ca/internationalawards/',
  application_url = 'https://registrar.mcmaster.ca/entrance-awards/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from McMaster University own pages read on 2026-10-25: future.mcmaster.ca/internationalawards gives the McMaster University Award of Excellence at up to CAD 200,000 over four years for international fee-paying students, the eligible faculties of Business, Engineering, Humanities, Science and Social Sciences, the application opening on 1 November 2026 and the deadline of 19 February 2027 at 11:59 p.m. Eastern, the renewal conditions requiring enrolment in the original faculty, full-time status and continued international tuition, and the faculty awards including the Global Dean Excellence Award at CAD 7,500 over four years; registrar.mcmaster.ca/entrance-awards states that McMaster holds over CAD 20 million in awards for international fee-paying undergraduates ranging from CAD 7,500 to 200,000, that awards are paid 50% after the fall drop-and-add period and 50% after the winter one, and that a change to domestic fees ends eligibility; the Faculty of Engineering page itemises the Engineering International Entrance Award and the Computer Science International Scholars Award at CAD 10,000 each and the CAD 35,000 x 4 year and CAD 7,500 x 4 year renewable engineering awards; the Science pages give the Science Global Scholars Award at CAD 10,000 on entry plus CAD 7,500 a year; the Social Science pages give CAD 10,000 in year one then CAD 5,000 a year for a total of CAD 25,000 at 85% or above, and CAD 2,500 below 85%. CORRECTIONS: the row was titled McMaster University International Entrance Scholarship, carried an invented USD 40,000, listed all three degree levels and said the deadline was not published. The real flagship is the Award of Excellence at up to CAD 200,000 over four years with a published 19 February 2027 deadline, and the row now names it. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the published ceiling of CAD 200,000.'
WHERE id = 622;

-- 659 Queen's — the Dean's International Award Program, automatic and faculty-specific
UPDATE scholarships SET
  title = 'Queen''s Dean''s International Award Program',
  description = 'Queen''s awards this automatically and the ladder is published faculty by faculty, which makes it one of the easiest international entrance awards in Canada to plan around: there is no application, no essay and no reference letter, and the award is assessed from the admission average. The Dean''s International Award Program has four ladders. Arts and Science pays CAD 5,000, 10,000, 15,000, 20,000 or 25,000 a year. Commerce pays CAD 15,000, 20,000 or 25,000. Engineering and Applied Science pays CAD 10,000, 15,000, 20,000 or 25,000. Health Sciences pays CAD 10,000 or 15,000 for the Bachelor of Health Sciences, and the Bachelor of Nursing is excluded. Every one of them is renewable for three further years, which puts the ceiling at CAD 100,000 over four years, provided the student stays registered full time in a program in the original faculty. Eligibility is limited to international students who are not Canadian citizens or permanent residents, including dual citizens, and who are entering post-secondary education for the first time and paying international tuition. Two smaller awards sit alongside: the Principal''s Global Scholars Undergraduate Award at CAD 7,000 for international students entering through the Global Scholars admission pathway for forcibly displaced students, and the International Admission Scholarship at CAD 9,000 for ten students, assessed automatically.',
  requirements = 'Be an international student who is not a Canadian citizen or permanent resident, including dual citizens, and be entering the first year of post-secondary education for the first time. Be admitted to a first-entry undergraduate program in the Faculty of Arts and Science, the Stephen J. R. Smith School of Engineering and Applied Science, the Smith School of Business for the Bachelor of Commerce, or the Faculty of Health Sciences for the Bachelor of Health Sciences. Pay international tuition, since students paying domestic tuition are not eligible. No application is required: Queen''s assesses the Dean''s International Award automatically from the admission average and states the level in the award offer. Remain registered full time in a program of study in the original faculty of admission to renew for the three following years. Bachelor of Nursing students are not eligible for the Health Sciences award. Graduates of a two-year CEGEP program transferring into second year remain eligible for admission scholarships.',
  coverage_type = 'Partial Tuition', award_basis = 'range', award_amount = 25000, award_currency = 'CAD', award_period = 'year',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based entrance award',
  tuition_coverage = 'CAD 5,000 to CAD 25,000 a year depending on the faculty and the admission average, renewable for three further years, so up to CAD 100,000 over four years. It is a tuition reduction and does not cover living costs.',
  english_requirements = 'The award sets no separate English score; the Queen''s admission English requirement for the chosen program applies.',
  required_documents = '["Queen''s admission application through OUAC","Academic transcripts used to calculate the admission average","Proof of international fee status","No separate scholarship application"]',
  deadline = 'No separate scholarship deadline; assessed automatically with the admission application and stated in the award offer',
  deadline_date = NULL, deadline_type = 'automatic', application_status = 'open',
  website_url = 'https://www.queensu.ca/registrar/financial-aid/specific-students/international',
  source_url = 'https://www.queensu.ca/registrar/financial-aid/specific-students/international',
  application_url = 'https://www.queensu.ca/registrar/financial-aid/no-application-required/future-students/automatic-awards',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the Queen''s University Registrar international and U.S. students page read on 2026-10-25, which describes the Dean''s International Award Program as requiring no application, gives the four faculty ladders - Arts and Science at CAD 5,000, 10,000, 15,000, 20,000 or 25,000 renewable; Commerce at CAD 15,000, 20,000 or 25,000 renewable; Engineering at CAD 10,000, 15,000, 20,000 or 25,000 renewable; Health Sciences at CAD 10,000 or 15,000 for the Bachelor of Health Sciences - states that each is renewable for three subsequent years while the student remains full time in the original faculty, limits eligibility to international students who are not Canadian citizens or permanent residents and who are entering post-secondary education for the first time, and excludes students paying domestic tuition and Bachelor of Nursing students; the same page lists the Principal''s Global Scholars Undergraduate Award at CAD 7,000 for the Global Scholars pathway for forcibly displaced students. The automatic awards page confirms the Principal''s Scholarship at CAD 7,000 for one year for students at the top of the competitive admission average. CORRECTIONS: the row was titled Queen''s University International Entrance Scholarship, carried an invented USD 38,000, listed all three degree levels and gave a February 1 deadline. There is no award by that name; the real instrument is the Dean''s International Award Program, it needs no application and therefore has no deadline, and the ceiling is CAD 25,000 a year rather than a single USD figure. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the top annual level of CAD 25,000.'
WHERE id = 659;

-- 721 University of Alberta — the automatic admission award, with the big application-based award noted
UPDATE scholarships SET
  title = 'University of Alberta International Admission Scholarship',
  description = 'This is the automatic award, and it is deliberately modest: the University of Alberta International Admission Scholarship pays up to CAD 10,000 based on the admission average, needs no application, and is assessed when the offer is made. The companion automatic award, the Regional Excellence Scholarship, pays up to CAD 5,000 to selected regions. The money that actually changes the arithmetic at Alberta is application-based and sits above these: the President''s International Distinction Scholarship pays up to CAD 120,000 over four years to 25 first-year students with a superior admission average and demonstrated leadership, and the International Leader Scholarship pays up to CAD 15,000 for leadership in school, community organisations, extracurriculars or work. Two further awards are restricted by nationality or faculty and are not open to a general applicant: the May Quon Undergraduate Scholarship at up to CAD 100,000 is for Chinese or Hong Kong citizens with self-declared financial need, and the Cora Martinson International Scholarship at up to CAD 56,000 is for Augustana Faculty. Alberta states plainly that it does not offer full scholarships to either domestic or international students. The single scholarship application for a September 2027 start opens on 1 October 2026; the international page gives 10 January 2027 as the deadline while the entrance scholarships page gives 15 February 2027, so treat 10 January as the safe date.',
  requirements = 'Be an international student applying to a direct-entry undergraduate program at the University of Alberta and be admitted with a superior admission average; the International Admission Scholarship is assessed from that average with no application. For the application-based awards, submit the single University of Alberta scholarship application through the Awards Portal, which McMaster-style assesses all application-based awards from one form. Hold a valid study permit for the awards reserved for visa students. Meet the academic and English entry requirements of the chosen program. Note the deadline discrepancy: the international entrance scholarships page gives 10 January 2027 and the entrance scholarships page gives 15 February 2027 for a September 2027 start, so file by 10 January. Students applying from a Canadian high school on a study permit are assessed under the separate international admission award rules for that cohort.',
  coverage_type = 'Partial Tuition', award_basis = 'range', award_amount = 10000, award_currency = 'CAD', award_period = 'one_time',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based entrance scholarships',
  tuition_coverage = 'Up to CAD 10,000 for the automatic International Admission Scholarship and up to CAD 15,000 for the International Leader Scholarship. The larger application-based President''s International Distinction Scholarship reaches CAD 120,000 over four years for 25 students a year. The University of Alberta states that it does not offer full scholarships.',
  english_requirements = 'The scholarships set no separate English score; the University of Alberta admission English requirement, typically IELTS 6.5 with no band below 6.0, applies to admission.',
  required_documents = '["University of Alberta admission application","Single scholarship application through the Awards Portal for application-based awards","Academic transcripts showing the admission average","Evidence of leadership and community involvement","Study permit or proof that one will be obtained","English proficiency evidence"]',
  deadline = 'The application-based round for a September 2027 start opens on 1 October 2026; the international page gives 10 January 2027 as the deadline and the entrance scholarships page gives 15 February 2027',
  deadline_date = '2027-01-10', deadline_type = 'fixed', application_status = 'upcoming',
  website_url = 'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html',
  source_url = 'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html',
  application_url = 'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/entrance-scholarships/index.html',
  verification_status = 'verified', source_reliability = 8, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from University of Alberta own pages read on 2026-10-25: ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships describes the International Admission Scholarship at up to CAN CAD 10,000 based on admission average, the Regional Excellence Scholarship at up to CAD 5,000, the President''s International Distinction Scholarship at up to CAD 120,000 payable over four years to 25 students a year with a superior admission average and demonstrated leadership, the International Leader Scholarship at up to CAD 15,000, the May Quon Undergraduate Scholarship at up to CAD 100,000 for Chinese or Hong Kong citizens with self-declared financial need, and the Cora Martinson International Scholarship at up to CAD 56,000 for Augustana Faculty; ualberta.ca/en/admissions/tuition-and-scholarships/entrance-scholarships states that the university does not offer full scholarships for either domestic or international students, that the scholarship application for September 2027 opens on 1 October 2026 and closes on 15 February 2027, and describes the international admission award for students attending high school in Canada on a study permit; the international students in Canada page gives 10 January 2027 as the application deadline, which conflicts with the 15 February date on the other page, so the earlier date is used and the discrepancy is recorded in the deadline text and in this note. CORRECTIONS: the row was titled University of Alberta International Admission Scholarship, which is correct, but carried an invented USD 21,500 and a vague January-March deadline. The award is up to CAD 10,000, one-time, automatic, and the deadlines Alberta publishes are 10 January 2027 and 15 February 2027 depending on the page. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the published CAD 10,000.'
WHERE id = 721;

-- 729 University of Calgary
UPDATE scholarships SET
  title = 'University of Calgary International Entrance Scholarship',
  description = 'Calgary keeps this one small and renewable, and the renewal rule is the part that matters. The University of Calgary International Entrance Scholarship pays CAD 20,000 and there are only two of them, but it renews in the second, third and fourth year, which puts the ceiling at CAD 80,000 over a degree. It is open to international students entering the first year of any undergraduate degree in the upcoming fall term who have already satisfied the English language proficiency requirement, and it is applied for through the My UCalgary Portal under the High School Prestige Awards competition, so an admission application alone is not enough. Renewal requires a GPA of 2.60 or higher over a minimum of 24.00 units in the previous fall and winter terms and continued payment of the international differential tuition fee as an international student. A separate University of Calgary International Entrance Award also pays CAD 20,000 to a variable number of students and is assessed through the High School Nominated Awards. Neither is a full ride: Calgary tells international students to arrange additional funding because its awards generally cover only part of tuition, fees and living costs, and there is no separate language-training allowance inside the scholarship.',
  requirements = 'Be an international student who is not a Canadian citizen or permanent resident and who is required to pay international tuition fees. Be entering the first year of an undergraduate degree at the University of Calgary in the upcoming fall term, in any faculty. Satisfy the university English language proficiency requirement for the chosen program before the award is assessed. Apply for admission first, then submit the High School Prestige Awards application through the My UCalgary Portal, because the entrance scholarship is not awarded automatically. To renew in years two to four, achieve a GPA of 2.60 or higher over at least 24.00 units in the previous fall and winter terms and keep paying international differential tuition. Note that entering the International Foundations Program does not make an applicant eligible for the international entrance awards.',
  coverage_type = 'Partial Funding', award_basis = 'fixed', award_amount = 20000, award_currency = 'CAD', award_period = 'year',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based entrance scholarship',
  tuition_coverage = 'CAD 20,000, renewable in years two to four at the same value, for a potential CAD 80,000 over four years. Only two awards are offered, and Calgary states that its awards cover only part of tuition, fees and living costs.',
  english_requirements = 'Applicants must have satisfied the University of Calgary English language proficiency requirement for the chosen program before the award is assessed; the scholarship does not include a language-training allowance.',
  required_documents = '["University of Calgary admission application","High School Prestige Awards application through the My UCalgary Portal","Academic transcripts used for admission","English language proficiency evidence","Proof of international fee status"]',
  deadline = 'The award is part of the High School Prestige Awards competition, applied for through the My UCalgary Portal; the award page does not publish a closing date',
  deadline_date = NULL, deadline_type = 'not_published', application_status = 'open',
  expected_deadline_period = 'The closing date is published inside the High School Prestige Awards competition pages rather than on the award page, so confirm it there before applying.',
  website_url = 'https://www.ucalgary.ca/registrar/awards/university-calgary-international-entrance-scholarship',
  source_url = 'https://www.ucalgary.ca/registrar/awards/university-calgary-international-entrance-scholarship',
  application_url = 'https://www.ucalgary.ca/registrar/awards/university-calgary-international-entrance-award',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two University of Calgary awards pages read on 2026-10-25: ucalgary.ca/registrar/awards/university-calgary-international-entrance-scholarship gives the award value as CAD 20,000 renewable, two awards, the My UCalgary Portal High School Prestige Awards as the application route, the description of the award as offered annually to undergraduate international students entering first year in any undergraduate degree in the upcoming fall term who have satisfied the English language proficiency requirement, and the renewal conditions of a GPA of 2.60 or more over a minimum of 24.00 units in the previous fall and winter terms while continuing to pay the international differential tuition fee; ucalgary.ca/registrar/awards/university-calgary-international-entrance-award gives the separate CAD 20,000 International Entrance Award with a variable number of awards assessed through the High School Nominated Awards. CORRECTIONS: the row carried an invented USD 21,000, claimed a March 1 deadline and listed all three degree levels. The award is CAD 20,000 renewable for up to CAD 80,000, it is undergraduate only, and the provider page publishes no closing date at all, so the deadline field now says so instead of inventing one. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the published CAD 20,000.'
WHERE id = 729;

-- 753 University of Ottawa — the single biggest automatic international award in this cluster
UPDATE scholarships SET
  title = 'University of Ottawa International English Admission Scholarship',
  description = 'Ottawa pays this automatically and pays it generously: the International English Admission Scholarship is worth CAD 7,500 per term, renewable for up to 12 instalments, which is CAD 60,000 over a four-year undergraduate degree, and the number of awards is unlimited for students who meet the conditions. There is no application - eligibility is assessed at admission and the award is granted on full-time enrolment. The conditions are a valid study permit, newly admitted status for the winter 2026 term or later in an approved English-language undergraduate program in Arts, Engineering, Health Sciences, Science, Social Sciences or the Telfer School of Management, a minimum admission average of 80%, full-time study and international tuition, and not being in the French Immersion stream. A second award stacks on top: the International English Academic Excellence Scholarship pays CAD 10,000 as CAD 5,000 per term, is not renewable, has 100 places and needs an admission average of 95% or higher, and it can be combined with the first award, which is how Ottawa reaches its published figure of up to CAD 70,000. Students in French or French Immersion have a different instrument, the Differential Tuition Fee Exemption Scholarship. Note that the separate, much larger Ottawa Entrance and Excellence Scholarships that pay up to CAD 100,000 over four years are restricted to students from Africa, Southeast Asia or the United States and do not apply to an applicant from Uzbekistan.',
  requirements = 'Be an international student holding a valid study permit. Be newly admitted for the winter 2026 term or later to an approved English-language undergraduate program in the Faculty of Arts, Engineering, Health Sciences, Science, Social Sciences or the Telfer School of Management. Have a minimum admission average of 80% for the International English Admission Scholarship, or 95% or higher for the 100-place International English Academic Excellence Scholarship. Enrol full time and pay international tuition, and stay out of the French Immersion stream. No separate scholarship application is required for either award: eligibility is assessed at admission and the scholarship is granted automatically on full-time enrolment. Renewal of the Admission Scholarship depends on continued full-time study in an eligible program, up to a maximum of 12 instalments.',
  coverage_type = 'Partial Tuition', award_basis = 'fixed', award_amount = 60000, award_currency = 'CAD', award_period = 'total',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition reduction scholarship',
  tuition_coverage = 'CAD 7,500 per term, for a maximum of 12 instalments, which is CAD 60,000 over four years. The optional CAD 10,000 Academic Excellence award brings the combined total to CAD 70,000. Living costs are not covered.',
  english_requirements = 'The scholarships set no separate English score, but they apply only to programs offered in English and require the English-language admission requirements of that program to be met.',
  required_documents = '["University of Ottawa admission application","Valid study permit","Academic transcripts showing the admission average","English proficiency evidence as the program requires","No separate scholarship application"]',
  deadline = 'No separate scholarship deadline; the awards are granted automatically at admission for the winter 2026 term onward, so the admission deadline of the chosen program is the operative date',
  deadline_date = NULL, deadline_type = 'automatic', application_status = 'open',
  website_url = 'https://www.uottawa.ca/study/fees-financial-support/international-english-scholarship',
  source_url = 'https://www.uottawa.ca/study/fees-financial-support/international-english-scholarship',
  application_url = 'https://www.uottawa.ca/study/fees-financial-support/scholarships-awards-overview',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from University of Ottawa own pages read on 2026-10-25: uottawa.ca/study/fees-financial-support/international-english-scholarship describes the International English Admission Scholarship at CAD 7,500 per term, CAD 60,000 over a four-year degree, unlimited awards, automatic, renewable up to 12 instalments, and the International English Academic Excellence Scholarship at CAD 10,000 paid as CAD 5,000 per term, 100 awards, not renewable but combinable with the first, giving the stated total of up to CAD 70,000; the same page gives the eligibility criteria of a valid study permit, new admission for winter 2026 or later in an approved English-language undergraduate program in Arts, Engineering, Health Sciences, Science, Social Sciences or the Telfer School of Management, and a minimum admission average of 80%; the scholarships overview page describes the French-stream Differential Tuition Fee Exemption Scholarship; the African, Southeast Asian and United States English-stream Entrance and Excellence Scholarships page shows the larger awards of up to CAD 100,000 over four years for Engineering, which are restricted by region and are not open to applicants from Uzbekistan. CORRECTIONS: the row was titled University of Ottawa International Entrance Scholarship, carried an invented USD 31,000, listed all three degree levels and gave an April 1 deadline. The real instrument is the International English Admission Scholarship at CAD 7,500 per term to a maximum of CAD 60,000, it needs no application and therefore has no scholarship deadline, and the row now names it. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the CAD 60,000 four-year maximum.'
WHERE id = 753;

-- 767 University of Waterloo — CAD 10,000 for every eligible international first-year, no cap
UPDATE scholarships SET
  title = 'University of Waterloo International Student Entrance Scholarship',
  description = 'Waterloo made this award simple and broad, which is unusual among Canadian universities: every international fee-paying student admitted to a full-time first-year degree program receives CAD 10,000 for their first-year studies, there is no application, and there is no limit on the number of students who receive it. It is paid in two instalments of CAD 5,000, the first in late July to help pay first-term tuition and the second in late November for the second term. It is available only in the first year and only against the first and second term tuition bills, and it does not replace or reduce any other Waterloo entrance scholarship - a student can hold it alongside the President and Merit scholarships and any faculty award. Two conditions apply: enrolment must be full time (three or more courses) in the first and second terms, and the student must remain an international fee-paying student, so a change of residency status before or during the term ends eligibility. The exclusions are specific: Medical Sciences at Waterloo and the Doctor of Medicine at St George''s University, Bachelor of Social Work, Doctor of Optometry, Doctor of Pharmacy, transfer students admitted with transfer credits, and students in 2+2 or similar programs. The provider text also lists students who deferred an offer from a previous year as excluded while its own FAQ says deferral preserves eligibility, so confirm that case directly. Several faculty awards reach much higher values, including the Faculty of Mathematics Global Scholarships at CAD 12,000 to 40,000 and Faculty of Science international scholarships at CAD 25,000 to 80,000.',
  requirements = 'Be an international fee-paying student admitted to a full-time first-year degree program at the University of Waterloo, including applicants from CEGEP and students admitted through the BASE program. No application, documents or bank information are required: eligible students see the award on the Awards and financial aid tab of the Waterloo applicant portal from April, and no specific grade average beyond the conditions of the offer is needed. Enrol full time, meaning three or more courses, in the first and second terms. Remain an international fee-paying student; a change of residency status before or during the term ends eligibility. Note the exclusions: Medical Sciences at Waterloo and the Doctor of Medicine at St George''s University, Bachelor of Social Work, Doctor of Optometry, Doctor of Pharmacy, transfer students admitted with transfer credits, and 2+2 or similar programs. Faculty awards with higher values, such as the Mathematics Global Scholarships and the Science international scholarships, are separate and some need an application.',
  coverage_type = 'Partial Tuition', award_basis = 'fixed', award_amount = 10000, award_currency = 'CAD', award_period = 'one_time',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Institutional entrance scholarship for international fee-paying students',
  tuition_coverage = 'CAD 10,000 applied to first-year tuition in two instalments of CAD 5,000. First year only, first and second term bills only. No living allowance.',
  english_requirements = 'The scholarship sets no separate English score; meeting the conditions of the offer of admission is sufficient.',
  required_documents = '["Waterloo admission application through OUAC","English proficiency evidence as the program requires","No separate scholarship application, documents or bank information"]',
  deadline = 'No separate scholarship deadline; eligibility is automatic on admission and the award appears in the applicant portal from mid-April',
  deadline_date = NULL, deadline_type = 'automatic', application_status = 'open',
  website_url = 'https://uwaterloo.ca/future-students/financing/international-scholarships',
  source_url = 'https://uwaterloo.ca/future-students/financing/international-scholarships',
  application_url = 'https://uwaterloo.ca/future-students/financing/scholarships',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the University of Waterloo scholarships for international students page fetched 2026-10-25, which states that international fee-paying students admitted to full-time first-year degree studies receive CAD 10,000 for their first-year studies, that no application is required, that the award is not available to Medical Sciences at Waterloo and the Doctor of Medicine at St George''s University, Bachelor of Social Work, Doctor of Optometry, Doctor of Pharmacy, transfer students admitted with transfer credits, students who deferred an offer of admission from a previous year and students in 2+2 or similar programs, that the first instalment of CAD 5,000 is available in late July and the second in late November, that it applies only to the first and second term tuition bills and only in the first year, that it does not replace or reduce other Waterloo entrance scholarships, that there are no limits on the number of recipients and no specific grade average beyond the conditions of the offer, that enrolment must be full time in both terms and international fee status maintained, and - in the same FAQ - that students who defer their offer remain eligible, which contradicts the exclusion list above it and is recorded here rather than resolved. The same page lists the Faculty of Mathematics Global Scholarships at up to 10 awards of CAD 12,000 to 40,000, the Faculty of Science international student scholarships at up to 15 awards of CAD 25,000 to 80,000, and the President and Merit scholarships. CORRECTIONS: the row was titled University of Waterloo International Student Entrance Scholarships, carried an invented USD 63,000, claimed Full Tuition, listed all three degree levels and gave a February 1 deadline. The real award is CAD 10,000, first year only, automatic and uncapped, and the CAD 63,000 figure matches no award on the page. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the published CAD 10,000.'
WHERE id = 767;

-- 790 Western — three CAD 100,000 awards through the National Scholarship Program
UPDATE scholarships SET
  title = 'Western International President''s Entrance Scholarships',
  description = 'Western runs its international entrance money through the National Scholarship Program, and the flagship is genuinely large: three International President''s Entrance Scholarships of CAD 100,000 each, paid as CAD 25,000 a year for four years. A fourth award sits beside them - the Neen Hodgins President''s International Entrance Scholarship, one at up to CAD 100,000, reserved for an international visa student entering Arts and Humanities. Getting in requires more than grades: the applicant must apply for admission through the OUAC to Western''s main campus, be nominated by their secondary school, and then submit the online National Scholarship application with an essay, a transcript provided by the school and a reference letter, all by the published deadline, which was 14 February 2026 for the 2026-27 round. Each school may nominate up to four students, plus one additional international visa student, so the nomination itself is a filter. The academic floor is a minimum overall average of 90% on all Grade 12 U/M courses or equivalent, and International Baccalaureate and CEGEP students are eligible. The scholarship is renewable for four years provided the recipient remains a full-time student. Students who are interviewed but not selected receive a one-year National Merit Award of CAD 2,000 and keep eligibility for an admission scholarship of CAD 2,500 to 8,000, so the application is not wasted.',
  requirements = 'Apply for admission to Western University main campus through the Ontario Universities Application Centre and register as a full-time student. Obtain a nomination from your secondary school: each school may nominate up to four students, plus one additional international visa student. Hold a minimum overall academic average of 90% on all Grade 12 U/M courses or equivalent; International Baccalaureate and CEGEP students are eligible. Submit the online National Scholarship application, which requires the OUAC reference number, together with the essay, a school-provided transcript and a reference letter, by the published deadline. International applicants use the international visa student version of the application. The published deadline for the 2026-27 round was 14 February 2026 and the application for 2027-28 becomes available by mid-November 2026. Continue as a full-time student to keep the award renewable over four years.',
  coverage_type = 'Partial Funding', award_basis = 'fixed', award_amount = 100000, award_currency = 'CAD', award_period = 'total',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based entrance scholarship',
  tuition_coverage = 'CAD 100,000 paid as CAD 25,000 a year for four years, for three International President''s Entrance Scholarships, plus one Neen Hodgins President''s International Entrance Scholarship at up to CAD 100,000 reserved for Arts and Humanities. It is a fixed four-year sum and is not described by Western as covering every cost.',
  english_requirements = 'The scholarship sets no separate English score; the Western admission English requirement for the chosen program applies.',
  required_documents = '["Admission application to Western main campus through OUAC","School nomination","Online National Scholarship application","Essay","Transcript provided by the school","Reference letter from the school"]',
  deadline = 'The published deadline for the 2026-27 round was 14 February 2026; the 2027-28 application becomes available by mid-November 2026',
  deadline_date = NULL, deadline_type = 'annual', application_status = 'upcoming',
  expected_deadline_period = 'Applications open by mid-November 2026 for the 2027-28 round and follow the published 14 February deadline pattern, with supporting documents received rather than postmarked by that date.',
  website_url = 'https://registrar.uwo.ca/student_finances/scholarships_awards/admission/national_scholarship_program.html',
  source_url = 'https://registrar.uwo.ca/student_finances/scholarships_awards/admission/national_scholarship_program.html',
  application_url = 'https://registrar.uwo.ca/student_finances/scholarships_awards/admission/national_scholarship_program.html',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the Western University Office of the Registrar National Scholarship Program page fetched 2026-10-25, which lists the International President''s Entrance Scholarships at 3 at CAD 100,000 and the Neen Hodgins President''s International Entrance Scholarship at one up to CAD 100,000 payable CAD 25,000 per academic year for four years, states that with the exception of the International President''s Entrance Scholarships and the President''s Entrance Scholarship for Black Students applicants must be Canadian citizens or permanent residents, requires a minimum overall academic average of 90% on all Grade 12U/M courses or equivalent, requires an admission application to the main campus through OUAC and full-time registration, requires a school nomination with each school able to nominate up to four students plus one additional international visa student, lists the online application components of application, school nomination, essay, transcript and reference letter, gives the published deadline of 14 February 2026 for the 2026-27 round with supporting documentation received rather than postmarked by that date, and states that the 2027-28 application becomes available by mid-November 2026; the same page lists the National Merit Award at CAD 2,000 for interviewed applicants who are not selected and confirms they retain eligibility for an admission scholarship of CAD 2,500 to 8,000. CORRECTIONS: the row carried an invented USD 32,000, listed all three degree levels and gave a 15 January deadline. The real award is three CAD 100,000 scholarships paid over four years, undergraduate only, and the deadline is mid-February with a mid-November opening, not 15 January. amount_usd_value is 0 because the provider publishes in Canadian dollars and award_amount carries the published CAD 100,000.'
WHERE id = 790;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = 'Yes', funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = true, covers_living_expenses = v.living, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (255, 'Dalhousie General Entrance Awards (International Applicants)', 'Merit-based and need-based', 'CAD 1,000 to CAD 80,000 per award, once or over four years', false, 'A portfolio of 2,000+ entrance awards entered through the General Entrance Award application. Typically an 80% average or 26 predicted IB points using the five required courses. The 2027-28 application opens 1 October 2026 and closes 15 February 2027. Transfer students generally excluded.', 'https://www.dal.ca/admissions/scholarships-financial-aid/scholarships/future-undergraduate-student-awards.html'),
  (138, 'McMaster University Award of Excellence', 'Merit-based and earned merit', 'Up to CAD 200,000 over four years', false, 'Application opens 1 November 2026 and closes 19 February 2027 at 11:59 p.m. Eastern through AwardSpring. Open to Business, Engineering, Humanities, Science and Social Sciences. Renewable in Levels 2-4 if the student stays in the original faculty, full-time, paying international tuition.', 'https://future.mcmaster.ca/internationalawards/'),
  (146, 'Queen''s Dean''s International Award Program', 'Merit-based', 'CAD 5,000 to CAD 25,000 a year, renewable for four years, up to CAD 100,000', false, 'Automatic, no application. Four faculty ladders: Arts and Science 5/10/15/20/25k, Commerce 15/20/25k, Engineering 10/15/20/25k, Health Sciences 10/15k. International fee-paying students entering post-secondary for the first time; Bachelor of Nursing excluded.', 'https://www.queensu.ca/registrar/financial-aid/specific-students/international'),
  (63, 'University of Alberta International Admission Scholarship', 'Merit-based', 'Up to CAD 10,000 automatic; up to CAD 120,000 for the President''s International Distinction Scholarship', false, 'The admission scholarship is automatic from the admission average. Application-based awards including the President''s International Distinction Scholarship (25 students a year) open 1 October 2026 with a 10 January 2027 deadline on the international page and 15 February 2027 on the entrance scholarships page.', 'https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html'),
  (110, 'University of Calgary International Entrance Scholarship', 'Merit-based', 'CAD 20,000 a year, renewable, up to CAD 80,000', false, 'Two awards, applied for through the My UCalgary Portal High School Prestige Awards. First year of any undergraduate degree; English language proficiency must be met. Renewal needs a 2.60 GPA over at least 24 units in the previous fall and winter terms.', 'https://www.ucalgary.ca/registrar/awards/university-calgary-international-entrance-scholarship'),
  (168, 'University of Ottawa International English Admission Scholarship', 'Merit-based tuition reduction', 'CAD 7,500 per term, up to CAD 60,000; a combinable CAD 10,000 award raises this to CAD 70,000', false, 'Automatic at admission, unlimited awards. Requires a valid study permit, 80% admission average, full-time study, international fees and an approved English-language program in Arts, Engineering, Health Sciences, Science, Social Sciences or Telfer. The 100-place CAD 10,000 Academic Excellence award needs 95%.', 'https://www.uottawa.ca/study/fees-financial-support/international-english-scholarship'),
  (64, 'University of Waterloo International Student Entrance Scholarship', 'Institutional entrance scholarship', 'CAD 10,000 in first year, paid as two instalments of CAD 5,000', false, 'No application and no cap on recipients: every international fee-paying first-year student in an eligible program receives CAD 10,000. Requires full-time enrolment in the first two terms and continued international fee status. Excludes Medical Sciences, Optometry, Pharmacy, Social Work, transfer students with credit and 2+2 programs.', 'https://uwaterloo.ca/future-students/financing/international-scholarships'),
  (200, 'Western International President''s Entrance Scholarships', 'Merit-based', 'CAD 100,000 over four years for three recipients, plus one Neen Hodgins award at up to CAD 100,000', false, 'Through the National Scholarship Program: OUAC application to main campus, school nomination (four per school plus one international visa student), online application with essay, transcript and reference letter, minimum 90% average. The 2027-28 round opens by mid-November 2026.', 'https://registrar.uwo.ca/student_finances/scholarships_awards/admission/national_scholarship_program.html')
) AS v(id, name, ftype, mx, living, elig, url)
WHERE u.id = v.id;
